import React, { useState } from 'react';
import { User, Github, Save, Edit3} from 'lucide-react';

const ProfilePage = () => {
  // 1. We use useState to store data that CHANGES (Dynamic Data)
  const [profileData, setProfileData] = useState({
    fullName: '',
    bio: '',
    github: '',
    portfolio: '',
    skills: ['React.js', 'Tailwind CSS'] // Initial skills
  });

  // 2. This function captures every keystroke and updates the state
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData({
      ...profileData,     // Keep existing data
      [name]: value       // Update only the field that changed
    });
  };

  const handleSave = () => {
    // In your graduation project, this is where you would call your API
    console.log("Saving to Database:", profileData);
    alert("Profile changes saved successfully!");
  };

  const styles = {
    container: { backgroundColor: '#fdfbff', minHeight: '100vh', padding: '40px 20px', fontFamily: 'Arial, sans-serif' },
    card: { backgroundColor: 'white', maxWidth: '850px', margin: '0 auto', borderRadius: '15px', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', overflow: 'hidden' },
    header: { backgroundColor: '#c5a3d1', height: '120px' },
    content: { padding: '30px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' },
    inputGroup: { marginBottom: '20px' },
    label: { display: 'block', fontSize: '14px', fontWeight: 'bold', color: '#555', marginBottom: '8px' },
    input: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd', outline: 'none', fontSize: '14px' },
    saveBtn: { backgroundColor: '#4a3f6b', color: 'white', padding: '12px 25px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '10px', margin: '20px auto' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}></div>
        
        <div style={{ padding: '0 30px', marginTop: '-50px' }}>
          <div style={{ width: '100px', height: '100px', borderRadius: '50%', backgroundColor: '#eee', border: '4px solid white', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <User size={50} color="#ccc" />
          </div>
          <h2 style={{ color: '#4a3f6b', marginTop: '10px' }}>{profileData.fullName || 'New User'}</h2>
        </div>

        <div style={styles.content}>
          {/* Column 1: Personal Details */}
          <div>
            <h3 style={{ fontSize: '18px', color: '#4a3f6b', borderBottom: '2px solid #f3e8ff', paddingBottom: '10px' }}>
              <Edit3 size={18} /> Personal Details
            </h3>
            
            <div style={styles.inputGroup}>
              <label style={styles.label}>Full Name</label>
              <input 
                type="text" 
                name="fullName" // Matches the key in state
                value={profileData.fullName} 
                onChange={handleChange} 
                style={styles.input}
                placeholder="Enter your name"
              />
            </div>

            <div style={styles.inputGroup}>
              <label style={styles.label}>Bio</label>
              <textarea 
                name="bio"
                value={profileData.bio}
                onChange={handleChange}
                style={{ ...styles.input, height: '80px', resize: 'none' }}
                placeholder="Short bio..."
              />
            </div>
          </div>

          {/* Column 2: Links & Skills */}
          <div>
            <h3 style={{ fontSize: '18px', color: '#4a3f6b', borderBottom: '2px solid #f3e8ff', paddingBottom: '10px' }}>
              <Github size={18} /> Links & Skills
            </h3>
            <div style={styles.inputGroup}>
              <label style={styles.label}>GitHub URL</label>
              <input 
                type="text" 
                name="github"
                value={profileData.github}
                onChange={handleChange}
                style={styles.input}
                placeholder="https://github.com/..."
              />
            </div>

            <div style={styles.inputGroup}>
              <label style={styles.label}>Portfolio</label>
              <input 
                type="text" 
                name="portfolio"
                value={profileData.portfolio}
                onChange={handleChange}
                style={styles.input}
                placeholder="https://yourwebsite.com"
              />
            </div>
          </div>
        </div>

        <button style={styles.saveBtn} onClick={handleSave}>
          <Save size={18} /> Save Profile Changes
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
